begin;
create function pg_temp.practice_assert(ok boolean,label text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'Practice QA failed: %',label;end if;end $$;
do $$
declare u uuid=gen_random_uuid(); staff uuid=gen_random_uuid(); outsider uuid=gen_random_uuid(); firm uuid; otherfirm uuid; h uuid; otherhouse uuid; tid uuid; run uuid; opp uuid; requestid uuid=gen_random_uuid(); p jsonb; result jsonb; firsttask public.crm_tasks; secondtask public.crm_tasks; blocked boolean; report jsonb;
begin
 insert into auth.users(id,email) values(u,'practice-qa-owner@example.invalid'),(staff,'practice-qa-staff@example.invalid'),(outsider,'practice-qa-outside@example.invalid');
 firm=(public.crm_dispatch(u,null,'firm.create','{"name":"QA practice rollback","is_demo":false}',gen_random_uuid())->>'id')::uuid;
 otherfirm=(public.crm_dispatch(outsider,null,'firm.create','{"name":"QA outside rollback","is_demo":false}',gen_random_uuid())->>'id')::uuid;
 perform set_config('app.crm_actor',u::text,true);
 insert into public.crm_members(firm_id,user_id,name,email,role) values(firm,staff,'QA Staff','practice-qa-staff@example.invalid','staff');
 h=(public.crm_dispatch(u,firm,'household.create',jsonb_build_object('name','QA practice household','stage','prospect','service_tier','Core','lead_advisor_id',u,'member_ids',jsonb_build_array(staff)),gen_random_uuid())->>'id')::uuid;
 otherhouse=(public.crm_dispatch(outsider,otherfirm,'household.create',jsonb_build_object('name','QA other household','stage','prospect','service_tier','Core','lead_advisor_id',outsider),gen_random_uuid())->>'id')::uuid;
 p='{"name":"QA two steps","description":"Synthetic test","steps":[{"title":"QA Step one","details":"Verify first","days":0},{"title":"QA Step two","details":"Then verify second","days":3}]}';
 tid=(public.crm_practice_dispatch(u,firm,'template.create',p,gen_random_uuid())->>'id')::uuid;
 blocked=false;begin perform public.crm_practice_dispatch(staff,firm,'template.create',p,gen_random_uuid());exception when others then blocked=true;end;perform pg_temp.practice_assert(blocked,'staff cannot change firm templates');
 p=jsonb_build_object('household_id',h,'template_id',tid,'assigned_to',staff,'start_on','2026-10-31');
 result=public.crm_practice_dispatch(staff,firm,'workflow.start',p,requestid);run=(result->>'id')::uuid;
 perform pg_temp.practice_assert(public.crm_practice_dispatch(staff,firm,'workflow.start',p,requestid)=result,'workflow retry does not duplicate');
 perform pg_temp.practice_assert((select count(*)=2 from public.crm_workflow_steps where run_id=run),'all ordered tasks created');
 select t.* into firsttask from public.crm_tasks t join public.crm_workflow_steps s on s.task_id=t.id where s.run_id=run and step_order=1;
 select t.* into secondtask from public.crm_tasks t join public.crm_workflow_steps s on s.task_id=t.id where s.run_id=run and step_order=2;
 perform pg_temp.practice_assert(firsttask.due_on='2026-10-31' and secondtask.due_on='2026-11-03','calendar day due offsets');
 p=to_jsonb(secondtask)||'{"status":"done"}';
 blocked=false;begin perform public.crm_dispatch(staff,firm,'task.update',p,gen_random_uuid());exception when others then blocked=true;end;perform pg_temp.practice_assert(blocked,'cannot complete future step early');
 perform public.crm_dispatch(staff,firm,'task.update',to_jsonb(firsttask)||'{"status":"done"}',gen_random_uuid());
 perform public.crm_dispatch(staff,firm,'task.update',p,gen_random_uuid());
 blocked=false;begin perform public.crm_dispatch(staff,firm,'task.update',to_jsonb(firsttask)||jsonb_build_object('status','open','version',firsttask.version+1),gen_random_uuid());exception when others then blocked=true;end;perform pg_temp.practice_assert(blocked,'cannot invalidate completed prerequisites');
 p=jsonb_build_object('id',tid,'version',1,'name','QA edited template','description','Future runs only','steps',jsonb_build_array(jsonb_build_object('title','Future one','details','','days',0)));
 perform public.crm_practice_dispatch(u,firm,'template.update',p,gen_random_uuid());
 perform pg_temp.practice_assert((select jsonb_array_length(template_snapshot->'steps')=2 from public.crm_workflow_runs where id=run),'started workflow keeps original template');
 p=jsonb_build_object('household_id',h,'title','QA potential assets','stage','proposal','owner_id',staff,'potential_assets',100000,'currency','CAD','expected_close','2026-11-30','notes','Fictional estimate, not account AUM');
 opp=(public.crm_practice_dispatch(staff,firm,'opportunity.create',p,gen_random_uuid())->>'id')::uuid;
 perform public.crm_practice_dispatch(staff,firm,'opportunity.update',p||jsonb_build_object('id',opp,'version',1,'stage','commitment'),gen_random_uuid());
 blocked=false;begin perform public.crm_practice_dispatch(staff,firm,'opportunity.update',p||jsonb_build_object('id',opp,'version',1),gen_random_uuid());exception when others then blocked=true;end;perform pg_temp.practice_assert(blocked,'stale opportunity edit rejected');
 blocked=false;begin perform public.crm_practice_dispatch(u,firm,'opportunity.create',p||jsonb_build_object('household_id',otherhouse),gen_random_uuid());exception when others then blocked=true;end;perform pg_temp.practice_assert(blocked,'owner cannot link another firm household');
 blocked=false;begin perform public.crm_practice_dispatch(outsider,firm,'workflow.start',jsonb_build_object('household_id',h,'template_id',tid,'assigned_to',outsider,'start_on','2026-10-31'),gen_random_uuid());exception when others then blocked=true;end;perform pg_temp.practice_assert(blocked,'cross-firm workflow denied');
 -- Same-firm unassigned households must also be absent from staff reports.
 otherhouse=(public.crm_dispatch(u,firm,'household.create',jsonb_build_object('name','QA private household','stage','active','service_tier','Core','lead_advisor_id',u),gen_random_uuid())->>'id')::uuid;
 perform public.crm_practice_dispatch(u,firm,'opportunity.create',p||jsonb_build_object('household_id',otherhouse,'owner_id',u,'potential_assets',900000),gen_random_uuid());
 perform pg_temp.practice_assert(not has_function_privilege('authenticated','public.crm_practice_dispatch(uuid,uuid,text,jsonb,uuid)','execute'),'clients cannot impersonate actor');
 perform set_config('request.jwt.claim.sub',staff::text,true);set local role authenticated;
 report=public.crm_practice_report(firm);
 perform pg_temp.practice_assert((report->>'workflow_count')::integer=1,'assigned staff report counts workflow');
 perform pg_temp.practice_assert((report->'pipeline'->0->>'potential_assets')::numeric=100000,'report sums potential assets');
 reset role;
 perform set_config('request.jwt.claim.sub',outsider::text,true);set local role authenticated;
 perform pg_temp.practice_assert((select count(*)=0 from public.crm_opportunities where firm_id=firm),'RLS hides other firm opportunities');
 report=public.crm_practice_report(firm);perform pg_temp.practice_assert((report->>'workflow_count')::integer=0 and jsonb_array_length(report->'pipeline')=0,'reports cannot leak other firm totals');reset role;
end $$;
select 'passed' as status;
rollback;
